import * as THREE from 'three';
import {compileSurface} from './engine.mjs';
import {number,meshBounds,sliceMesh,stitch,plot} from './analysis.mjs';
import {wireCoordinates,renderCoordinates} from './integral-panel.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
export function createExplorer(api){
  const group=new THREE.Group(),seams=new THREE.Group(),markers=new THREE.Group();api.scene.add(group,seams,markers);let result=null,pointNodes=[],clickStart=null;
  api.renderer.localClippingEnabled=true;
  function clear(g){for(const o of [...g.children]){g.remove(o);o.traverse(c=>{c.geometry?.dispose();if(c.material){c.material.map?.dispose();c.material.dispose();}});}}
  function line(segments,color,width=1){const p=segments.flatMap(s=>s.flat());const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(p,3));return new THREE.LineSegments(g,new THREE.LineBasicMaterial({color,linewidth:width,depthTest:false,transparent:true,opacity:.95}));}
  function selected(){const b=result?.body;if(!b)return new Float32Array();const r=b.regions?.find(r=>String(r.index)===$('regionSelect').value);return r?b.positions.subarray(r.start*3,(r.start+r.vertices)*3):b.positions;}
  function bounds(){const p=selected();return p.length?meshBounds(p):api.getBounds();}
  function updateIntersections(){clear(seams);clear(markers);if(!result)return;const selectedRegion=result.body?.regions?.find(r=>String(r.index)===$('regionSelect').value);let data=result.body?.analyses?.[selectedRegion?selectedRegion.index:'all']||result.analysis||{segments:[],points:[]};
    seams.add(line(data.segments.map(s=>[s.a,s.b]),'#ffdc92'));pointNodes=data.points;const span=Math.max(...bounds().map(b=>b[1]-b[0]));
    for(const [i,n]of pointNodes.entries()){const m=new THREE.Mesh(new THREE.SphereGeometry(span*.009,12,8),new THREE.MeshBasicMaterial({color:'#ffdb91',depthTest:false}));m.position.set(...n.p);m.userData.point=n;markers.add(m);const l=api.label('P'+(i+1),'#f6d9a2',span*.045);l.position.set(...n.p);l.position.z+=span*.04;markers.add(l);}
    $('pointList').replaceChildren();for(const [i,n]of pointNodes.entries()){const b=document.createElement('button');b.className='point-chip';b.textContent=`P${i+1} (${n.p.map(number).join(', ')})`;b.onclick=()=>showPoint(n.p,n.sources.map(s=>result.body.fieldIds[s]));$('pointList').append(b);}
    $('intersectionNote').textContent=`高亮 ${data.segments.length?'曲面交线':'交线：当前未提取到'} · ${pointNodes.length} 个边界关键点（网格近似）`;seams.visible=$('showIntersections').checked;markers.visible=$('showPoints').checked;
  }
  function showPoint(p,ids=[]){const names=api.getRows().filter(r=>ids.includes(r.id)).map(r=>r.expr);$('pointReadout').textContent=`(${p.map(number).join(', ')})${names.length?' · '+names.join('；'):''}`;document.querySelectorAll('.surface-card').forEach(c=>c.classList.toggle('inspected',ids.includes(c.dataset.id)));}
  function slice(){clear(group);const axis=+$('sliceAxis').value,b= bounds(),lo=b[axis][0],hi=b[axis][1],p=selected(),other=[0,1,2].filter(d=>d!==axis),value=+$('sliceNumber').value;
    $('sliceSlider').min=lo;$('sliceSlider').max=hi;$('sliceSlider').step=(hi-lo)/500||.001;$('sliceSlider').value=value;$('sliceNumber').step=(hi-lo)/500||.001;
    const seg=sliceMesh(p,axis,value),span=Math.max(...b.map(b=>b[1]-b[0])),loops=stitch(seg.map(s=>s.map(p=>other.map(d=>p[d]))),span*1e-6).filter(p=>p.length>3&&Math.hypot(...p[0].map((v,d)=>v-p.at(-1)[d]))<span*1e-5);
    const polygons=loops.map(p=>p.slice(0,-1));plot($('sliceCanvas'),{bounds:other.map(d=>b[d]),segments:seg.map(s=>s.map(p=>other.map(d=>p[d]))),labels:other.map(d=>'xyz'[d])});
    const ctx=$('sliceCanvas').getContext('2d');if(polygons.length){const view=plot($('sliceCanvas'),{bounds:other.map(d=>b[d]),segments:seg.map(s=>s.map(p=>other.map(d=>p[d]))),labels:other.map(d=>'xyz'[d])});view.ctx.beginPath();for(const poly of polygons){poly.forEach((p,i)=>{const[x,y]=view.xy(p);i?view.ctx.lineTo(x,y):view.ctx.moveTo(x,y);});view.ctx.closePath();}view.ctx.fillStyle='#efba6966';view.ctx.fill('evenodd');}
    $('sliceNote').textContent=p.length?`${'xyz'[axis]} = ${number(value)} · ${loops.length?'显示闭合截面轮廓':'此位置未切出闭合截面'}`:'生成立体后拖动滑块，观察截面变化。';
    const clipping=$('cutBody').checked&&$('showSlice').checked,plane=new THREE.Plane(new THREE.Vector3().setComponent(axis,-1),value);
    for(const m of [...api.bodyGroup.children,...seams.children]){const changed=!!m.material.clippingPlanes?.length!==clipping;m.material.clippingPlanes=clipping?[plane]:[];if(changed)m.material.needsUpdate=true;}for(const m of markers.children)m.visible=!clipping||m.position.getComponent(axis)<=value+span*1e-5;
    if(!$('showSlice').checked||!p.length)return;
    const to3=p=>{const q=[0,0,0];q[axis]=value;other.forEach((d,i)=>q[d]=p[i]);return q;};
    group.add(line(seg,'#c7eff4'));
    const planePositions=[[b[other[0]][0],b[other[1]][0]],[b[other[0]][1],b[other[1]][0]],[b[other[0]][1],b[other[1]][1]],[b[other[0]][0],b[other[1]][1]]].map(to3);
    const planeG=new THREE.BufferGeometry().setFromPoints([0,1,2,0,2,3].map(i=>new THREE.Vector3(...planePositions[i])));planeG.computeVertexNormals();group.add(new THREE.Mesh(planeG,new THREE.MeshBasicMaterial({color:'#95d9e3',transparent:true,opacity:.09,side:THREE.DoubleSide,depthWrite:false})));
    // Nested loops are assigned as holes before triangulation, preserving annular sections.
    const inside=(p,poly)=>{let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])yes=!yes;}return yes;};
    const nodes=polygons.map(poly=>({poly,parents:polygons.filter(q=>q!==poly&&inside(poly[0],q))}));
    for(const n of nodes.filter(n=>n.parents.length%2===0)){const shape=new THREE.Shape(n.poly.map(p=>new THREE.Vector2(...p)));for(const h of nodes.filter(h=>h.parents.length===n.parents.length+1&&inside(h.poly[0],n.poly)))shape.holes.push(new THREE.Path(h.poly.map(p=>new THREE.Vector2(...p))));const g=new THREE.ShapeGeometry(shape),v=g.attributes.position;for(let i=0;i<v.count;i++){const p=to3([v.getX(i),v.getY(i)]);v.setXYZ(i,...p);}g.computeVertexNormals();group.add(new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:'#9fd9dc',transparent:true,opacity:clipping?.94:.58,side:THREE.DoubleSide,depthWrite:false})));}
  }
  function projection(){const p=selected(),key=$('projectionPlane').value,ds=[...'xyz'].map((_,i)=>i).filter(i=>key.includes('xyz'[i])),polygons=[];for(let i=0;i<p.length;i+=9)polygons.push([0,3,6].map(k=>ds.map(d=>p[i+k+d])));plot($('projectionCanvas'),{bounds:ds.map(d=>bounds()[d]),polygons,labels:ds.map(d=>'xyz'[d]),color:api.getColor()});$('projectionNote').textContent=p.length?`立体在 ${key} 平面的投影 D · 同一坐标单位等比例显示`:'投影对应外层积分的区域。';}
  function limits(){const r=result?.body?.regions?.find(r=>String(r.index)===$('regionSelect').value)||result?.body?.regions?.[0],rows=api.getRows();if(renderCoordinates({region:r,rows,params:api.getParams(),preset:api.getPreset?.(),multiple:$('regionSelect').value==='all'&&result?.body?.regions?.length>1}))return;$('boundaryList').replaceChildren();if(!r){$('integralHint').textContent='输入曲面并生成有界立体后，显示边界约束与积分顺序提示。';return;}
    for(const s of r.sides){const row=rows.find(x=>x.id===s.id);if(!row)continue;try{const c=compileSurface(row.expr),el=document.createElement('div');el.className='boundary-expression';el.textContent=`${c.lhs} ${s.side==='le'?'≤':'≥'} ${c.rhs}`;$('boundaryList').append(el);}catch{}}
    const order=$('integralOrder').value,inner=order[0],outer=order.slice(1).split('').sort().join(''),graph=[];for(const s of r.sides){const row=rows.find(x=>x.id===s.id);if(!row)continue;const c=compileSurface(row.expr);if(c.lhs.trim()===inner&&!c.rhs.includes(inner))graph.push({side:s.side,expr:c.rhs});if(inner==='z'&&c.lhs.replace(/\s/g,'').split('+').sort().join(',')==='x,y,z'&&!c.rhs.includes('z'))graph.push({side:s.side,expr:`(${c.rhs})−x−y`});}
    let text=`积分次序 d${order.split('').join(' d')}：先沿 ${inner} 方向取线段，再在 ${outer} 平面的投影 D 上积分。`;
    if(graph.length){const lower=graph.filter(g=>g.side==='ge').map(g=>g.expr),upper=graph.filter(g=>g.side==='le').map(g=>g.expr);text+=` 内层下界：${lower.length?lower.length>1?'max('+lower.join(', ')+')':lower[0]:'由其余边界确定'}；上界：${upper.length?upper.length>1?'min('+upper.join(', ')+')':upper[0]:'由其余边界确定'}。`;if(lower.length+upper.length>2)text+=' max / min 的主导边界变化处需要分段。';}
    const sample=r.sides.map(s=>rows.find(x=>x.id===s.id)?.expr.replace(/\s/g,''));if(inner==='z'&&sample.includes('x+y+z=2')&&sample.some(s=>s==='z=xy'||s==='z=x*y')&&sample.includes('z=0'))text+=' 此例 D：0≤x≤2，0≤y≤2−x；沿 y=(2−x)/(x+1) 分段，上界分别为 xy 与 2−x−y。';
    const preset=api.getPreset?.(),hints={sphere:'R>0 时，xy 投影为 x²+y²≤R²；−√(R²−x²−y²)≤z≤√(R²−x²−y²)。',ellipsoid:'a,b,c>0 时，xy 投影为 x²/a²+y²/b²≤1；z 的上下界为 ±c√(1−x²/a²−y²/b²)。',bowl:'a>0 时，xy 投影为 x²+y²≤a；x²+y²≤z≤a。',hemisphere:'R>0 时，xy 投影为 x²+y²≤R²；0≤z≤√(R²−x²−y²)。',tetra:'a>0 时，0≤x≤a，0≤y≤a−x，0≤z≤a−x−y。',twobowls:'a>0 时，x²+y²≤a/2；x²+y²≤z≤a−x²−y²。',solidcylinder:'R,h>0 时，xy 投影为 x²+y²≤R²；0≤z≤h。',capcone:'h>0 时，xy 投影为 x²+y²≤h²；√(x²+y²)≤z≤h。'};if(preset)text+=' 常见模型（以 dz 为内层）：'+(hints[preset.id]||preset.hint);
    text+=' 任意隐式边界以所列约束和投影为准；数值包围框不是解析积分限。';$('integralHint').textContent=text;
  }
  function refresh(){if(!result||document.querySelector('.analysis-workbench').getAttribute('aria-busy')==='true')return;slice();projection();limits();}
  $('sliceAxis').onchange=()=>{const b=bounds()[+$('sliceAxis').value];$('sliceNumber').value=(b[0]+b[1])/2;$('sliceSlider').value=$('sliceNumber').value;slice();};
  let sliceFrame=null;const queueSlice=()=>{if(sliceFrame!==null)return;sliceFrame=requestAnimationFrame(()=>{sliceFrame=null;slice();});};
  $('sliceSlider').oninput=()=>{$('sliceNumber').value=$('sliceSlider').value;queueSlice();};$('sliceNumber').oninput=()=>{if(Number.isFinite(+$('sliceNumber').value)){$('sliceSlider').value=$('sliceNumber').value;queueSlice();}};
  for(const id of['showSlice','cutBody'])$(id).onchange=slice;$('projectionPlane').onchange=projection;$('integralOrder').onchange=limits;
  $('showIntersections').onchange=()=>seams.visible=$('showIntersections').checked;$('showPoints').onchange=()=>markers.visible=$('showPoints').checked;
  api.renderer.domElement.addEventListener('pointerdown',e=>clickStart=[e.clientX,e.clientY]);api.renderer.domElement.addEventListener('pointerup',e=>{if(!clickStart||Math.hypot(e.clientX-clickStart[0],e.clientY-clickStart[1])>5)return;const rect=api.renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,1-(e.clientY-rect.top)/rect.height*2),api.getCamera());const points=ray.intersectObjects(markers.children).filter(h=>h.object.userData.point);if(points.length){const n=points[0].object.userData.point;showPoint(n.p,n.sources.map(s=>result.body.fieldIds[s]));return;}const hits=ray.intersectObjects([...api.surfaceGroup.children,...api.bodyGroup.children],true).filter(h=>h.object.visible&&h.object.parent.visible);if(hits.length){const h=hits[0],id=h.object.parent.userData.rowId;if(h.object.userData.regionIndex!==undefined&&h.point.getComponent(+$('sliceAxis').value)>+$('sliceNumber').value&&$('cutBody').checked)return;showPoint(h.point.toArray(),id?[id]:[]);}});
  wireCoordinates(limits);new ResizeObserver(refresh).observe($('sliceCanvas'));
  return{update(data){group.visible=true;result=data;updateIntersections();const b=bounds()[+$('sliceAxis').value],v=+$('sliceNumber').value;if(v<b[0]||v>b[1])$('sliceNumber').value=(b[0]+b[1])/2;$('sliceSlider').value=$('sliceNumber').value;refresh();},pending(){group.visible=false;seams.visible=false;markers.visible=false;},refresh,select(){updateIntersections();refresh();}};
}
